//! What a person may choose for the hotspot, and the checks and defaults for it: the network name, the passphrase (generated by
//! default, from the operating system's random source), how many clients, how long it may sit idle before it switches itself off.

use std::fmt;

pub const SSID_MAX: usize = 32;
pub const PASSPHRASE_MIN: usize = 8;
pub const PASSPHRASE_MAX: usize = 63;
pub const MAX_CLIENTS_LIMIT: u8 = 32;
pub const DEFAULT_MAX_CLIENTS: u8 = 8;
pub const DEFAULT_IDLE_HOURS: u8 = 2;
pub const IDLE_HOURS_LIMIT: u8 = 72;

/// Letters and digits without 0 O 1 I l: 32 symbols, so five random bits make one character without bias.
const ALPHABET: &[u8; 32] = b"23456789ABCDEFGHJKLMNPQRSTUVWXYZ";

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SettingsError {
    SsidEmpty,
    SsidTooLong,
    SsidBadChar,
    PassphraseTooShort,
    PassphraseTooLong,
    PassphraseBadChar,
    ClientsOutOfRange,
    IdleOutOfRange,
    Random,
}

impl fmt::Display for SettingsError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            SettingsError::SsidEmpty => "the network name is empty",
            SettingsError::SsidTooLong => "the network name is longer than 32 bytes",
            SettingsError::SsidBadChar => "the network name has a control character",
            SettingsError::PassphraseTooShort => "the passphrase needs at least 8 characters",
            SettingsError::PassphraseTooLong => "the passphrase has at most 63 characters",
            SettingsError::PassphraseBadChar => "the passphrase may only use printable ASCII characters",
            SettingsError::ClientsOutOfRange => "the number of devices must be 1 to 32",
            SettingsError::IdleOutOfRange => "the idle time must be 1 to 72 hours",
            SettingsError::Random => "no random numbers are available",
        })
    }
}

/// The default network name: `IYAKKI-` and the last four letters or digits of the device id, upper case (padded with 0).
pub fn default_ssid(device_id: &str) -> String {
    let mut tail: Vec<char> = device_id.chars().filter(|c| c.is_ascii_alphanumeric()).map(|c| c.to_ascii_uppercase()).collect();
    while tail.len() < 4 {
        tail.insert(0, '0');
    }
    let last: String = tail[tail.len() - 4..].iter().collect();
    format!("IYAKKI-{last}")
}

pub fn validate_ssid(s: &str) -> Result<(), SettingsError> {
    if s.is_empty() {
        return Err(SettingsError::SsidEmpty);
    }
    if s.len() > SSID_MAX {
        return Err(SettingsError::SsidTooLong);
    }
    if s.chars().any(|c| c.is_control()) {
        return Err(SettingsError::SsidBadChar);
    }
    Ok(())
}

pub fn validate_passphrase(p: &str) -> Result<(), SettingsError> {
    if p.len() < PASSPHRASE_MIN {
        return Err(SettingsError::PassphraseTooShort);
    }
    if p.len() > PASSPHRASE_MAX {
        return Err(SettingsError::PassphraseTooLong);
    }
    if !p.bytes().all(|b| (0x20..=0x7e).contains(&b)) {
        return Err(SettingsError::PassphraseBadChar);
    }
    Ok(())
}

/// A hint for a passphrase a person typed (None when it looks fine). Never a reason to refuse.
pub fn passphrase_warning(p: &str) -> Option<&'static str> {
    let lower = p.to_ascii_lowercase();
    if p.len() < 12 {
        return Some("a short passphrase can be guessed offline from a recorded connection; use 12 or more characters");
    }
    let first = p.as_bytes().first().copied().unwrap_or(0);
    if p.bytes().all(|b| b == first) || ["12345678", "password", "qwertyui", "iyakki"].iter().any(|w| lower.contains(w)) {
        return Some("this passphrase is easy to guess");
    }
    None
}

/// A passphrase of 16 random characters in four groups (`K7MQ-2XWD-9PRT-HC4N`, 80 bits), drawn with `fill`.
pub fn generate_passphrase_with(fill: &mut dyn FnMut(&mut [u8]) -> bool) -> Result<String, SettingsError> {
    let mut b = [0u8; 16];
    if !fill(&mut b) {
        return Err(SettingsError::Random);
    }
    let mut out = String::with_capacity(19);
    for (i, x) in b.iter().enumerate() {
        if i > 0 && i % 4 == 0 {
            out.push('-');
        }
        out.push(ALPHABET[(x & 31) as usize] as char);
    }
    Ok(out)
}

/// The same with the operating system's random bytes (`iyakki_sec::random_fill`).
pub fn generate_passphrase() -> Result<String, SettingsError> {
    generate_passphrase_with(&mut |b| iyakki_sec::random_fill(b).is_ok())
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct HotspotSettings {
    pub ssid: String,
    pub passphrase: String,
    pub max_clients: u8,
    pub idle_hours: u8,
    /// Devices on the hotspot cannot reach each other.
    pub client_isolation: bool,
}

impl HotspotSettings {
    /// Fresh settings for a device: default name, a generated passphrase, isolation on.
    pub fn new_default(device_id: &str) -> Result<HotspotSettings, SettingsError> {
        Ok(HotspotSettings { ssid: default_ssid(device_id), passphrase: generate_passphrase()?, max_clients: DEFAULT_MAX_CLIENTS, idle_hours: DEFAULT_IDLE_HOURS, client_isolation: true })
    }

    pub fn validate(&self) -> Result<(), SettingsError> {
        validate_ssid(&self.ssid)?;
        validate_passphrase(&self.passphrase)?;
        if self.max_clients == 0 || self.max_clients > MAX_CLIENTS_LIMIT {
            return Err(SettingsError::ClientsOutOfRange);
        }
        if self.idle_hours == 0 || self.idle_hours > IDLE_HOURS_LIMIT {
            return Err(SettingsError::IdleOutOfRange);
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_default_name_uses_the_last_four_characters_of_the_device_id() {
        assert_eq!(default_ssid("a1b2c3d4-9f3e"), "IYAKKI-9F3E");
        assert_eq!(default_ssid("xy"), "IYAKKI-00XY");
        assert_eq!(default_ssid(""), "IYAKKI-0000");
        assert_eq!(default_ssid("ab-cd"), "IYAKKI-ABCD");
        assert!(validate_ssid(&default_ssid("whatever")).is_ok());
    }

    #[test]
    fn names_and_passphrases_are_checked() {
        assert_eq!(validate_ssid(""), Err(SettingsError::SsidEmpty));
        assert_eq!(validate_ssid(&"a".repeat(33)), Err(SettingsError::SsidTooLong));
        assert_eq!(validate_ssid("ab\ncd"), Err(SettingsError::SsidBadChar));
        assert!(validate_ssid(&"a".repeat(32)).is_ok());
        assert!(validate_ssid("Küche 5").is_ok());
        assert_eq!(validate_ssid(&"ü".repeat(17)), Err(SettingsError::SsidTooLong), "the limit is bytes");
        assert_eq!(validate_passphrase("short"), Err(SettingsError::PassphraseTooShort));
        assert_eq!(validate_passphrase(&"x".repeat(64)), Err(SettingsError::PassphraseTooLong));
        assert_eq!(validate_passphrase("ünicode-pass"), Err(SettingsError::PassphraseBadChar));
        assert_eq!(validate_passphrase("tab\there-12"), Err(SettingsError::PassphraseBadChar));
        assert!(validate_passphrase(&"x".repeat(63)).is_ok());
        assert!(validate_passphrase("with spaces ok").is_ok());
    }

    #[test]
    fn warnings_are_hints_for_short_or_obvious_passphrases() {
        assert!(passphrase_warning("abcdefgh").is_some());
        assert!(passphrase_warning("aaaaaaaaaaaaaaaa").is_some());
        assert!(passphrase_warning("my-password-is-long").is_some());
        assert!(passphrase_warning("K7MQ-2XWD-9PRT").is_none());
    }

    #[test]
    fn a_generated_passphrase_has_the_right_shape_and_comes_from_the_random_bytes() {
        let p = generate_passphrase_with(&mut |b| {
            for (i, x) in b.iter_mut().enumerate() {
                *x = i as u8;
            }
            true
        })
        .unwrap();
        assert_eq!(p, "2345-6789-ABCD-EFGH");
        assert_eq!(generate_passphrase_with(&mut |_| false), Err(SettingsError::Random));
        let a = generate_passphrase().unwrap();
        let b = generate_passphrase().unwrap();
        assert_ne!(a, b);
        for p in [&a, &b] {
            assert_eq!(p.len(), 19);
            assert!(validate_passphrase(p).is_ok());
            assert!(p.chars().all(|c| c == '-' || ALPHABET.contains(&(c as u8))));
            assert!(passphrase_warning(p).is_none());
        }
    }

    #[test]
    fn every_symbol_of_the_alphabet_is_reachable_and_unambiguous() {
        let mut seen = std::collections::BTreeSet::new();
        for x in 0..=255u8 {
            seen.insert(ALPHABET[(x & 31) as usize]);
        }
        assert_eq!(seen.len(), 32);
        assert!(!ALPHABET.iter().any(|c| b"01OIl".contains(c)));
    }

    #[test]
    fn default_settings_are_safe_and_limits_are_enforced() {
        let s = HotspotSettings::new_default("0011223344556677").unwrap();
        assert_eq!((s.ssid.as_str(), s.max_clients, s.idle_hours, s.client_isolation), ("IYAKKI-6677", 8, 2, true));
        assert!(s.validate().is_ok());
        assert_eq!(HotspotSettings { max_clients: 0, ..s.clone() }.validate(), Err(SettingsError::ClientsOutOfRange));
        assert_eq!(HotspotSettings { max_clients: 33, ..s.clone() }.validate(), Err(SettingsError::ClientsOutOfRange));
        assert_eq!(HotspotSettings { idle_hours: 0, ..s.clone() }.validate(), Err(SettingsError::IdleOutOfRange));
        assert_eq!(HotspotSettings { idle_hours: 73, ..s }.validate(), Err(SettingsError::IdleOutOfRange));
    }
}
